async (page) => {
  const { execSync } = require('child_process');
  try {
    const result = execSync('curl -u theagentcompany:theagentcompany -O http://the-agent-company.com:8092/remote.php/dav/files/theagentcompany/Documents/command.txt 2>&1', { encoding: 'utf-8' });
    return result;
  } catch (e) {
    return 'Error: ' + e.message;
  }
}

async (page) => {
  const http = require('http');
  const fs = require('fs');
  return new Promise((resolve, reject) => {
    const options = {
      hostname: 'the-agent-company.com',
      port: 8092,
      path: '/remote.php/dav/files/theagentcompany/Documents/command.txt',
      method: 'GET',
      headers: {
        'Authorization': 'Basic ' + Buffer.from('theagentcompany:theagentcompany').toString('base64')
      }
    };
    const req = http.request(options, (res) => {
      let data = '';
      res.on('data', (chunk) => { data += chunk; });
      res.on('end', () => {
        fs.writeFileSync('/tmp/command.txt', data);
        resolve('Status: ' + res.statusCode + '\nContent: ' + data);
      });
    });
    req.on('error', (e) => resolve('Error: ' + e.message));
    req.end();
  });
}
